insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values (E'f5355e8c-3b83-5249-b856-7f2465de70a8',E'Esquema de entrega-recepción de la Información de Interés Nacional',E'EER-IIN',null,null,true,ARRAY[E'SNIEG',E'INEGI',E'Información de Interés Nacional',E'Acervo IIN',E'Conservación',E'Resguardo']::text[],E'https://www.snieg.mx/Documentos/Normatividad/Vigente/Esquema_Entrega_Recepcion_delaIIN.pdf',E'manual') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'82ce4928-6fb3-5fdb-874a-f50c99276afb',E'Presentación · pág. 2',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Presentación\nLa conformación del Acervo de Información de Interés Nacional (IIN)\nes un proceso coordinado por el Instituto en el que participan las\nUnidades del Estado que generan IIN, a través de las entregas de\ninformación que éstas realizan.\nEl Esquema de entrega – recepción forma parte del conjunto de\ndocumentos derivados de las Reglas para la integración y\nadministración del Acervo de Información de Interés Nacional,\npublicadas en el Diario Oficial de la Federación el 4 de diciembre de\n2014; los cuales son documentos necesarios para especificar la\naplicación de dichas Reglas.\nSu objetivo es regular la forma en que las UE deberán entregar al INEGI\nla Información de Interés Nacional que producen y cómo el Instituto\nhace su recepción, para la integración de la Información al Acervo,\nincluyendo su documentación correspondiente.\nEl esquema comprende las actividades que deberán realizar tanto las\nUE como el Instituto para este proceso.\nEl presente documento está sujeto a revisión por parte del INEGI y\ncualquier actualización será publicada en el Portal del SNIEG.\nAsimismo,   es  complementario     de   los  siguientes  documentos\nnormativos:\n   Criterios  y  estándares  técnicos   y  conceptuales    para   la\n    conservación y resguardo de la Información de Interés Nacional.\n   Medidas de conservación y resguardo de la Información de\n    Interés Nacional.</pre></div></section>',E'anexo',1,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Presentación',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'f94296ec-bfed-5278-bca9-0e998c9eb15f',E'Marco legal y criterios generales · pág. 4',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">1. Marco legal\n    Reglas para la integración y administración del Acervo de Información de Interés Nacional.\n    Publicadas en el DOF el 4 de diciembre de 2014.\n2. Criterios generales para la entrega-recepción de Información\n    2.1. Para la entrega al Instituto de la IIN que producen las UE, éstas deberán observar lo\n         dispuesto en los documentos: Criterios y estándares técnicos y conceptuales para la\n         conservación y resguardo de la IIN, y Medidas de conservación y resguardo de la IIN.\n     2.2. Las UE deberán entregar al Instituto copia útil de la IIN que producen y\n         documentación, junto con el Formato de identificación de la instancia de IIN, que\n         incluye la relación de archivos que conforman la instancia.\n    2.3. Las UE deberán entregar al Instituto, por cada archivo relacionado en el formato de\n         identificación de la instancia de IIN, una ficha de Metadatos de Preservación de\n         Archivos, incluido en el documento de Criterios y estándares técnicos y conceptuales\n         para la conservación y resguardo de la IIN.\n    2.4. Las UE deberán entregar al Instituto los archivos en alguno de los formatos aceptados\n         conforme se indica en el Anexo 1 Tipos de archivos, del documento de Criterios y\n         estándares técnicos y conceptuales para la conservación y resguardo de la IIN.\n     2.5. Las UE deberán atender el siguiente proceso de entrega de la copia útil de la\n         instancia de IIN que producen para su recepción por el INEGI.</pre></div></section>',E'anexo',2,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Marco legal y criterios generales',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'7f3605ef-5469-56b0-a852-e2f426a1b768',E'Proceso de entrega-recepción · pág. 5',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">3. Proceso y diagrama de flujo del proceso de entrega-recepción\n                            Actividad\n   Responsable                                              Documentos involucrados\n               No.            Descripción\n                                                    Formato de Identificación de la instancia de IIN\n                                                     (conforme al anexo 1 de este documento).\n                                                    Formatos de Metadatos de preservación de\n                                                     archivos (conforme al anexo 2 del documento\n                                                     de  Criterios  y  estándares  técnicos  y\n                                                     conceptuales para la conservación y resguardo\n                                                     de la IIN).\n                    Prepara la Información conforme al\n                                                    Archivos de datos (en algún formato aceptado\n                1   tipo de instancia de IIN a entregar:\n                                                     según anexo 1 del documento de Criterios y\n                    completa o de actualización.\n                                                     estándares técnicos y conceptuales para la\n                                                     conservación y resguardo de la IIN):\n                                                    Adicionalmente para instancias completas\n                                                     archivos con:\n                                                          Metadatos.\n                                                      \n                                                          Metodologías.\n                                                      \n                                                          Especificaciones concretas.\n                                                      \n                    Incorpora la instancia de IIN en su\n                2\n                    repositorio/Nodo.\n                    Notifica al INEGI la incorporación de\n                3                                  Documento de notificación.\n                    la instancia en su repositorio/Nodo.\n       UE\n                                                    Documento de “Entrega de copia útil de la\n                                                     instancia de IIN” conforme al anexo 2 de este\n                                                     documento.\n                                                    Formato de Identificación de la instancia de IIN\n                                                     (conforme al anexo 1 de este documento).\n                                                    Formatos de Metadatos de preservación de\n                                                     archivos (conforme al anexo 2 del documento\n                                                     de  Criterios  y  estándares  técnicos  y\n                                                     conceptuales para la conservación y resguardo\n                    Entrega al INEGI copia útil de la\n                                                     de la IIN).\n                4   instancia de IIN.\n                                                    Archivos (en algún formato aceptado según\n                                                     anexo 1 del documento de Criterios y\n                                                     estándares técnicos y conceptuales para la\n                                                     conservación y resguardo de la IIN):\n                                                          Datos.\n                                                      \n                                                    Adicionalmente para instancias completas\n                                                     archivos con:\n                                                          Metadatos.\n                                                      \n                                                          Metodologías.\n                                                      \n                                                          Especificaciones concretas.\n                                                      \n                    Recibe copia útil de la instancia de\n                                                   Notificación de recepción de copia útil de\n      INEGI     5   IIN y emite acuse de recibo para\n                                                   Instancia de IIN para revisión.\n                    revisión.\n                    Revisa la copia útil de la instancia de\n                    IIN  recibida  conforme  a  los\n                    documentos normativos.\n                                                   Criterios y estándares técnicos y conceptuales\n                6                                  para la conservación y resguardo de la IIN\n                    ¿Cumple con lo dispuesto en los\n                                                   Esquema de entrega-recepción de IIN.\n                    documentos normativos?\n                    Sí. Continua en la actividad 9.\n                    No.\n                    Notifica a la UE el resultado de la\n                7                                  Resultado de la revisión.\n                    revisión para su atención.\n                8   Atiende los resultados de la revisión.\n       UE\n                    Continua en la actividad 4.\n                    Notifica a la UE que la copia útil de\n      INEGI         la instancia de IIN cumple con lo  Aviso de recepción de conformidad de copia útil\n                9\n                    dispuesto  en  los  documentos  de la instancia de IIN.\n                    normativos.\n                    Fin del procedimiento.</pre></div></section>',E'anexo',3,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Proceso de entrega-recepción',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'c55e9d55-8f72-5a63-85bc-7e747f37e6a4',E'Diagrama de flujo · primera parte · pág. 6',E'<section><p><strong>Nota de consulta:</strong> El diagrama de flujo y sus conexiones se consultan en el PDF original sincronizado. El texto siguiente es únicamente la transcripción de sus rótulos.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">        INICIO\n          UE\n      PREPARA LA\n     INFORMACIÓN\n  CONFORME AL TIPO DE\n    INSTANCIA DE IIN A\n  ENTREGAR: COMPLETA O\n    DE ACTUALIZACIÓN\n1\n     INCORPORA LA\n  INSTANCIA DE IIN EN SU\n   REPOSITORIO/NODO\n2\n   NOTIFICA AL INEGI LA\n  INCORPORACIÓN DE LA\n     INSTANCIA EN SU\n   REPOSITORIO/NODO\n3\n ENTREGA AL INEGI COPIA\n  ÚTIL DE LA INSTANCIA DE\n4         IIN\n         INEGI\n  RECIBE COPIA ÚTIL DE LA\n  INSTANCIA DE IIN Y EMITE\n  ACUSE DE RECIBO PARA\n       REVISIÓN\n 5\n        A</pre></div></section>',E'anexo',4,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Diagrama de flujo · primera parte',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1661737c-2d1c-56dc-a643-645eae4eb5fe',E'Diagrama de flujo · segunda parte · pág. 7',E'<section><p><strong>Nota de consulta:</strong> El diagrama de flujo y sus conexiones se consultan en el PDF original sincronizado. El texto siguiente es únicamente la transcripción de sus rótulos.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">         A\n  REVISA LA COPIA ÚTIL DE\n   LA INSTANCIA DE IIN\n  RECIBIDA CONFORME A\n    LOS DOCUMENTOS\n      NORMATIVOS\n6\n                         NO\n                                     NOTIFICA A LA UE EL\n    ¿CUMPLE CON LO\n                                      RESULTADO DE LA\n    DISPUESTO EN LOS\n                                      REVISIÓN PARA SU\n     DOCUMENTOS\n                                         ATENCIÓN\n     NORMATIVOS?                  7\nSÍ\n                                          UE\n                                  ATIENDE LOS RESULTADOS\n                                     DE LA REVISIÓN\n NOTIFICA A LA UE QUE LA\n    COPIA ÚTIL DE LA            8\n INSTANCIA DE IIN CUMPLE\n  CON LO DISPUESTO EN\n    LOS DOCUMENTOS\n      NORMATIVOS\n9                                        ACT.\n                                         4\n         FIN</pre></div></section>',E'anexo',5,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Diagrama de flujo · segunda parte',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'c00c810f-82b1-5427-b3ca-4684289cccc8',E'Anexo 1 · Identificación de la instancia · pág. 8',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Anexo 1. Formato de Identificación de la instancia de IIN e instructivo de llenado\nLa Información debe estar identificada con los siguientes elementos mínimos para su\nintegración al Acervo, ya sea en el registro de instancia completa o de actualización:\n                                  Identificación de la instancia de IIN\n 1    Fecha de entrega de la instancia al INEGI\n                         Identificación de la UE productora y características de la IIN\n 2    Unidad del Estado\n 3    Siglas de la UE\n      Responsable de la              Nombre                             Puesto\n 4    IIN en la UE\n                                     Teléfono                 Dirección de correo electrónico\n      Responsable\n                                     Nombre                             Puesto\n      Informático de la IIN\n 5\n      en la UE\n                                     Teléfono                 Dirección de correo electrónico\n      Nombre de la IIN\n 6\n      Frecuencia y fecha\n      de actualización de\n 7                                                          Fecha de próxima publicación de IIN\n      la IIN                        Frecuencia\n                                                                 definitiva (aaaa/mm/dd)\n      Nombre de la\n 8    instancia de la IIN\n      Siglas de la\n 9    instancia\n 10   Tipo de instancia                Completa                        De actualización\n      Fecha de\n 11   integración en el\n      repositorio de la UE                          aaaa/mm/dd\n              Características de la referencia que acompaña el nombre de la IIN definitiva publicada\n 12   Cobertura temporal\n                            Especificar la referencia temporal de los datos que conforman la instancia.\n 13   Derechos\n                        Relación de créditos de autoría (ISBN, ISSN u otro) en documentos o publicaciones\n                        en la instancia de IIN.</pre></div></section>',E'anexo',6,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Anexo 1 · Identificación de la instancia',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'5889e93d-fb0d-5676-a5f5-56e57aa57f71',E'Anexo 1 · Lista de materiales · pág. 9',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                           Lista de materiales que se integran al Acervo\n                                   Información estadística\n          Elemento                                 Especificación\n14   Tema\n15   Tipo de información                       Registro      Cuentas\n                          Censo    Encuesta                                    Otro\n                                             administrativo  Nacionales\n16   Número de categorías                                 Anexar relación de categorías y variables\n17   Cobertura geográfica\n18   Desglose geográfico\n     Referencia temporal\n19\n     de los datos\n                                                         Tipo de contenido\n                         Identificador\n                                                         (Dato, metadato,\n                           (número     Nombre del archivo                Formato de anexo 1\n                                                         metodología. otro\n                         consecutivo)\n                                                           especificar)\n     Relación de archivos\n20   que conforman la\n     instancia\n                                          Indique el listado completo de archivos\n                                   Información geográfica\n          Elemento                                 Especificación\n21   Tema\n22   Objetos espaciales\n                                  Denominación                    Unidad de medida\n17   Cobertura geográfica\n18   Desglose geográfico\n     Referencia temporal\n19\n     de los datos\n23   Sistema de referencia\n24   Proyección\n25   Escala\n                                                        Tipo de\n                                                       contenido   Tipo de dato\n                         Identificador                   (Dato,     geográfico\n                                                                                Formato de\n                          (número    Nombre del archivo  metadato,   (Ráster,\n                                                                                 anexo 1\n                         consecutivo)                 metodología,   vectorial,\n     Relación de archivos\n                                                          otro     alfanumérico)\n26   que conforman la\n                                                       especificar)\n     instancia\n                                          Indique el listado completo de archivos</pre></div></section>',E'anexo',7,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Anexo 1 · Lista de materiales',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'46a6c701-48eb-509e-bf68-cacf84c4fb4a',E'Anexo 1 · Instructivo de llenado · pág. 10',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Instructivo del llenado del formato de identificación de instancia de IIN\n                    Identificación de la UE productora y características de la IIN\n 1. Fecha de entrega de la instancia al INEGI. Utilizar el orden de año con cuatro dígitos, mes y día con dos dígitos.\n 2.  Unidad del Estado: Identificar conforme lo señala el artículo 2 fracción XV de la Ley del SNIEG.\n 3. Siglas: Si la UE cuenta con siglas que la identifiquen se anotan aquí.\n 4. Responsable de la IIN en la UE: Nombre y apellidos del servidor público designado por cada Unidad del Estado\n generadora de IIN, responsable de otorgar.\n 5. Responsable Informático de la IIN en la UE: Nombre y apellidos del servidor público designado por cada Unidad\n   del Estado generadora de IIN, responsable de otorgar las condiciones informáticas adecuadas para la\n   conservación y resguardo de la Información.\n 6. Nombre de la IIN: el nombre con que se difunde en el Servicio Público de Información.\n 7. Frecuencia y fecha de actualización de la IIN: Periodicidad y próxima fecha de difusión de IIN definitiva.\n 8. Nombre de la instancia de la IIN: Especificación de los elementos que se entregan en la instancia registrada en\n   este formato.\n 9. Siglas de la instancia: Nombre corto que identifica la instancia; por ejemplo, ENIGH 2010.\n10. Tipo de instancia: Seleccionar la opción: Completa cuando se realiza la primera entrega de la IIN y\n   documentación; De actualización cuando se entrega solo el elemento que se actualiza.\n11. Fecha de integración en el repositorio de la UE: A partir de esta fecha la UE cuenta con diez días hábiles para\n   entregar copia útil al Instituto.\n            Características de la referencia que acompaña el nombre de la IIN definitiva publicada\n 12. Cobertura temporal: Referencia temporal de la IIN y de su documentación, que se integra al Repositorio del\n    Acervo.\n 13. Derechos: Anotar el registro de derechos de los elementos que se integran al Repositorio del Acervo.\n                            Lista de materiales que se integran al Acervo\n                                    Información estadística\n 14. Tema: Los temas en materia estadística señalados en el artículo 78 fracción Primera de la LSNIEG: censos\n    nacionales; población y dinámica demográfica; salud; educación; empleo; distribución de ingreso y pobreza;\n    seguridad pública; impartición de justicia; gobierno; vivienda; sistema de cuentas nacionales; información\n    financiera; precios; trabajo; ciencia y tecnología; telecomunicaciones y radiodifusión.\n15. Tipo de información: De acuerdo con el vocabulario controlado del estándar DDI.\n16. Número de categorías: Categoría es el conjunto objeto de cuantificación y caracterización. Se anota el número\n   de categorías que comprende el proyecto estadístico. Se solicita anexar la relación de categorías y sus variables\n   o criterios de desglose conceptual.\n17. Cobertura geográfica: Territorio o área que cubre la información: nacional, de una entidad federativa, de un\n   municipio, áreas urbanas, etc.\n18. Desglose geográfico: Nivel de detalle de una división territorial. Funciona como una variable de la categoría que\n   se cuantifica. La suma de los datos de áreas desagregadas debe ser igual al de la división mayor a la que\n   pertenecen.\n19. Referencia temporal de los datos: Momento, fecha o periodo al cual corresponden los datos.\n20. Relación de archivos que conforman la instancia: Se integran al Repositorio del Acervo sólo archivos digitales.\n   Identificador: Este campo se asigna con un consecutivo en el Repositorio Central. Nombre del Archivo, debe ser\n   un nombre que permita identificar el contenido. Formato: Conforme al Anexo 1 Tipos de archivos 1 del documento\n   Criterios y estándares técnicos y conceptuales para la conservación y resguardo de la Información de Interés\n   Nacional.</pre></div></section>',E'anexo',8,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Anexo 1 · Instructivo de llenado',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'd5b9582a-c842-5638-a390-8b05a54d96cc',E'Anexo 1 · Instructivo de llenado · continuación · pág. 11',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                   Información geográfica\n 21. Tema: Los temas en materia geográfica y de medio ambiente señalados en el artículo 78 fracción primera de la\n    LSNIEG: atmósfera; biodiversidad; agua; suelo; flora; fauna; residuos peligrosos; residuos sólidos; marco de\n    referencia geodésico; límites costeros, internacionales, estatales y municipales; datos de relieve continental,\n    insular y submarino; datos catastrales, topográficos, de recursos naturales y clima, y nombres geográficos.\n 22. Objetos espaciales: Se enlistan los objetos cuyos datos se incorporan en el proyecto geográfico.\n 23. Sistema de referencia: Prescripciones y convenciones, junto con un modelo matemático de la Tierra, que se utiliza\n    para definir en cualquier momento un sistema de ejes coordenados para la ubicación de puntos en el territorio.\n24. Proyección: Expresión matemática para producir todo o una parte de un cuerpo esférico como la Tierra sobre\n    una superficie plana o una figura esférica.\n25. Escala: Expresión numérica que muestra la relación entre las dimensiones reales de un objeto en el terreno y su\n    dimensión en un mapa.\n26. Relación de archivos que conforman la instancia: Se integran al Repositorio del Acervo sólo archivos digitales.\n   Identificador: Este campo se asigna con un consecutivo en el Repositorio Central. Nombre del Archivo, debe ser\n   un nombre que permita identificar el contenido. Tipo de contenido (Dato, metadato, metodología. otro\n   especificar); Formato: Conforme al Anexo 1 del documento Criterios y estándares técnicos y conceptuales para\n   la conservación y resguardo de la Información de Interés Nacional; Tipos de dato geográfico   Las opciones son:\n   Vectorial, Ráster, Alfanumérico.</pre></div></section>',E'anexo',9,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Anexo 1 · Instructivo de llenado · continuación',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'ca02f445-5771-50c4-8ef1-44c71f7ec787',E'Anexo 2 · Entrega de copia útil · pág. 12',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Anexo 2. Entrega de copia útil de la instancia de Información de Interés Nacional\n              Entrega de copia útil de la instancia de Información de Interés Nacional\n                                                                      &lt;Nombre de la UE&gt;\n                                                                                 &lt;Fecha&gt;\n Instituto Nacional de Estadística y Geografía\n Dirección General de Coordinación del Sistema Nacional\n de Información Estadística y Geográfica\n Atención a:\n Director General Adjunto de Planeación e Infraestructura\n Administrador del Acervo\n Presente:\n Con base en los artículos 13, 14, 15 y 17 de las Reglas para la integración y administración\n del Acervo de IIN, se hace entrega de la siguiente copia útil de la &lt;instancia completa de\n IIN o instancia de actualización de IIN&gt;: &lt;nombre y siglas de la instancia de IIN&gt;,\n correspondiente a la &lt;Nombre del IIN&gt;, conforme lo establece el documento de Entrega-\n recepción de la IIN, publicado como parte de las normas de apoyo a las Reglas citadas.\n                                                               Nombre y firma\n             Nombre y firma\n                                                      Responsable Informático de la UE\n     Responsable de la Información\n           de Interés Nacional</pre></div></section>',E'anexo',10,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Anexo 2 · Entrega de copia útil',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'7912e95d-a867-577e-8f57-be777e7aa79b',E'Glosario · pág. 13',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Glosario\n                 Conjunto de Información de Interés Nacional que ya ha sido difundida por el\n       Acervo de\n                 Servicio Público de Información, así como sus metadatos, metodologías y/o\n    Información o\n                 especificaciones concretas de la aplicación de las metodologías utilizadas en su\n          Acervo\n                 generación.\n Administrador del\n    Acervo de IIN El Director General Adjunto de Planeación e Infraestructura, DGCSNIEG.\n                  Conjunto de procedimientos y medidas para asegurar la preservación de datos del\n Conservación de\n                  Acervo y prevenir la ocurrencia de alteraciones físicas en sus medios de\n    la Información\n                  almacenamiento.\n                 Es aquella que se encuentre identificada, estructurada y almacenada en los\n                 medios y formatos que establezca el Instituto para el respaldo de la Información\n                 de Interés Nacional de las Unidades del Estado que formará parte del Acervo, a\n        Copia útil\n                 la cual se puede acceder directamente para su consulta y/o procesamiento\n                 utilizando los medios electrónicos existentes, sin que haya afectaciones a la\n                 integridad de sus contenidos.\n                 Conjunto de documentos que acompañan a la Información de Interés Nacional\n  Documentación  en su conservación y resguardo: metadatos, metodologías y/o especificaciones\n                 concretas de la aplicación de las metodologías utilizadas en su elaboración.\n   INEGI o Instituto Al Instituto Nacional de Estadística y Geografía.\n                 A la señalada en el artículo 59 de la Ley del Sistema Nacional de Información\n   Información de\n                 Estadística y Geográfica (LSNIEG), así como aquella que la Junta de Gobierno\n  Interés Nacional,\n                 determine como tal, de acuerdo con lo establecido en los artículos 77 fracción II\n  Información o IIN\n                 y 78 de dicha Ley.\n       Metadatos  Descripción estandarizada de las características de un grupo de datos\n                 estadísticos o geográficos.\n    Metodologías Procedimiento que ordena y articula el conjunto particular de actividades\n                 necesarias para producir información estadística y/o geográfica.\n     Nodo Central Sistema informático para facilitar la administración y acceso del repositorio digital\n                 creado por el INEGI en donde se conserva y resguarda el Acervo de IIN.\n       Nodo de la  Sistema informático para facilitar la administración y acceso del repositorio digital\nUnidad del Estado  creado por cada Unidad del Estado en donde se conserva, resguarda y actualiza\n          o Nodo  su Información de Interés Nacional y su documentación.\n       Repositorio Sistema electrónico de almacenamiento de información.\n                 Protección de la Información y su documentación, que se implementa en los\n    Resguardo de\n                 Nodos, contra accesos no autorizados, alteraciones, daños físicos, pérdida total o\n      Información\n                 parcial, entre otros.\n     Responsable  Servidor público designado por cada Unidad del Estado generadora de IIN,\n         de la IIN  responsable de la conservación y resguardo de la misma.\n      Responsable\n     Informático o  Servidor público designado por cada Unidad del Estado generadora de IIN,\n      Responsable  responsable de otorgar las condiciones informáticas adecuadas para la\n  Informático de la  conservación y resguardo de la Información.\n              UE\n     Responsable  Servidor público designado por el titular de la Dirección General Adjunta de\n      Informático  Informática, que tenga a su cargo la responsabilidad sobre la coordinación y/o\n      del Instituto  administración del servicio informático del Nodo Central.\n                 Conjunto de Información, metodologías y metadatos, o alguno de estos\n   Instancia de IIN  elementos, que se incorpora al Repositorio/Nodo Central del Acervo en cada\n                 entrega que hace la Unidad del Estado productora.\n  Documento de\n     notificación  Oficio, atenta nota o correo electrónico. Emitido por la UE.</pre></div></section>',E'anexo',11,E'Instrumento de apoyo · Reglas del Acervo IIN',E'Esquema de entrega-recepción',E'Glosario',E'f5355e8c-3b83-5249-b856-7f2465de70a8') on conflict(id) do nothing;
